, \'-\', -1) = \'8XL\' OR SPLIT_PART(a.sku, \'-\', -1) = \'50\' THEN \'XL8\' else null end, a.sku, a.sku_group, a.total_inventory, b.live_date_final, b.category, b.sku_class, a.date ), total_size_pre as ( select sku_group, date, least(count(case when size in (\'30\',\'S\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'32\',\'M\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'34\',\'L\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'36\',\'XXL\',\'XXL\', \'XXl\', \'2XL\',\'38\') and total_inventory = 0 then size end),1) as cut_sizes, least(count(case when size in (\'28\',\'XS\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'30\',\'S\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'32\',\'M\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'34\',\'L\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'36\',\'XXL\',\'XXL\', \'XXl\', \'2XL\',\'38\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'3XL\',\'40\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'4XL\',\'42\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'5XL\',\'44\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'6XL\',\'46\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'7XL\',\'48\') and total_inventory = 0 then size end),1) + least(count(case when size in (\'8XL\',\'50\') and total_inventory = 0 then size end),1) as final_cut_sizes, least(count(case when size in (\'28\',\'XS\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'30\',\'S\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'32\',\'M\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'34\',\'L\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'36\',\'XXL\',\'XXL\', \'XXl\', \'2XL\',\'38\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'3XL\',\'40\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'4XL\',\'42\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'5XL\',\'44\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'6XL\',\'46\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'7XL\',\'48\') and total_inventory >= 5 then size end),1) + least(count(case when size in (\'8XL\',\'50\') and total_inventory >= 5 then size end),1) as sizes_above_5, least(count(case when size in (\'28\',\'XS\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'30\',\'S\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'32\',\'M\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'34\',\'L\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'36\',\'XXL\',\'XXL\', \'XXl\', \'2XL\',\'38\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'3XL\',\'40\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'4XL\',\'42\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'5XL\',\'44\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'6XL\',\'46\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'7XL\',\'48\') and total_inventory >= 10 then size end),1) + least(count(case when size in (\'8XL\',\'50\') and total_inventory >= 10 then size end),1) as sizes_above_10, least(count(case when size in (\'28\',\'XS\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'30\',\'S\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'32\',\'M\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'34\',\'L\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'36\',\'XXL\',\'XXL\', \'XXl\', \'2XL\',\'38\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'3XL\',\'40\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'4XL\',\'42\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'5XL\',\'44\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'6XL\',\'46\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'7XL\',\'48\') and total_inventory >= 40 then size end),1) + least(count(case when size in (\'8XL\',\'50\') and total_inventory >= 40 then size end),1) as sizes_above_40, least(count(case when size in (\'28\',\'XS\') and total_inventory <5 then size end),1) + least(count(case when size in (\'30\',\'S\') and total_inventory <5 then size end),1) + least(count(case when size in (\'32\',\'M\') and total_inventory <5 then size end),1) + least(count(case when size in (\'34\',\'L\') and total_inventory <5 then size end),1) + least(count(case when size in (\'36\',\'XXL\',\'XXL\', \'XXl\', \'2XL\',\'38\') and total_inventory <5 then size end),1) + least(count(case when size in (\'3XL\',\'40\') and total_inventory <5 then size end),1) + least(count(case when size in (\'4XL\',\'42\') and total_inventory <5 then size end),1) + least(count(case when size in (\'5XL\',\'44\') and total_inventory <5 then size end),1) + least(count(case when size in (\'6XL\',\'46\') and total_inventory <5 then size end),1) + least(count(case when size in (\'7XL\',\'48\') and total_inventory <5 then size end),1) + least(count(case when size in (\'8XL\',\'50\') and total_inventory <5 then size end),1) as cut_sizes_below_5, least(count(case when size in (\'28\',\'XS\') and total_inventory <10 then size end),1) + least(count