,c.price,d.cost_price from Final_inventory_calculation a left join total_size b on a.sku_group = b.sku_group and a.date = b.date LEFT JOIN PRICE C ON a.sku_group = c.sku_group left join cost_price d on a.sku = d.sku where sku_class != \'4-New-Not-Sold\' ), inv_check as ( select date, sku_group, \'no_inv\' as type, sum(total_inventory) as inv from final_check group by 1,2,3 having sum(total_inventory) = 0 ), style as ( select sku_group, style from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by status desc) = 1 ), cat_cut_size_pre as ( select a.*, coalesce(b.type,\'inv\') as inv_filter, c.style from final_check a left join inv_check b on a.sku_group = b.sku_group and a.date = b.date left join style c on a.sku_group = c.sku_group ), cat_cut_size as ( select category, date, sum(total_size) as cat_total_size, sum(cut_sizes) as cat_cut_sizes, sum(cut_sizes_below_10) as cat_cut_sizes_below_10, sum(cut_sizes_below_5) as cat_cut_sizes_below_5, sum(final_cut_sizes) as cat_final_cut_sizes, sum(sizes_above_5) as cat_sizes_above_5, sum(sizes_above_10) as cat_sizes_above_10, sum(sizes_above_40) as cat_sizes_above_40 from (select date, sku_group, category, inv_filter, max(total_size) as total_size, max(cut_sizes) as cut_sizes, max(cut_sizes_below_10) as cut_sizes_below_10, max(final_cut_sizes) as final_cut_sizes, max(cut_sizes_below_5) as cut_sizes_below_5, max(sizes_above_5) as sizes_above_5, max(sizes_above_10) as sizes_above_10, max(sizes_above_40) as sizes_above_40 from cat_cut_size_pre group by 1,2,3,4 ) where inv_filter = \'inv\' group by 1,2 ), sort_rank_pre as ( select a.*, cat_total_size, cat_cut_sizes, cat_cut_sizes_below_10, cat_cut_sizes_below_5, cat_final_cut_sizes, cat_sizes_above_5, cat_sizes_above_10, cat_sizes_above_40 from cat_cut_size_pre a left join cat_cut_size b on a.date = b.date and a.category = b.category ), sort_rank as ( select sku_group, sort_rank, global_sort_score from snitch_db.maplemonk.products_db_copy where status = \'active\' and sku_group is not null and sort_rank != 0 qualify row_number() over (partition by sku_group order by sort_rank asc) = 1 ), sku_group_inv as ( select sku_group, date, sum(total_inventory) as skugroup_inv from ( select a.*, b.sort_rank, b.global_sort_score from sort_rank_pre a left join sort_rank b on a.sku_group = b.sku_group ) group by 1,2 ) select a.*, b.sort_rank, b.global_sort_score, c.skugroup_inv from sort_rank_pre a left join sort_rank b on a.sku_group = b.sku_group left join sku_group_inv c on a.sku_group = c.sku_group and a.date = c.date ); create or replace table snitch_db.maplemonk.dod_all_channels_sku_inventory as ( WITH inv as ( select date, sku_group, sum(total_inventory)::INT as inv from cut_size_analysis where date >= \'2024-05-30\' group by 1,2 UNION ALL select date, SKU_GROUP, sum(inventory)::int AS INV from offline_master_daily_report_1 group by 1,2 ) SELECT DATE, SKU_GROUP, SUM(INV) as inv from inv group by 1,2 ); create or replace table snitch_db.maplemonk.cut_size_sales as with cut_size as ( SELECT date, SKU_GROUP AS SKU_GROUP, CUT_SIZES AS CUT_SIZES, sum(TOTAL_INVENTORY) AS Total_Inventory, FROM snitch_db.maplemonk.cut_size_analysis WHERE cut_sizes >= 2 AND ((INV_FILTER = \'inv\') AND (CUT_SIZES != 0)) and date >= \'2025-07-01\' GROUP BY 1,2,3 having sum(TOTAL_INVENTORY) <= 50 ), cut_size_formation_date as ( select sku_group, total_inventory as cut_size_formation_inv, date as cut_size_formation_date from cut_size qualify row_number() over (partition by sku_group order by date asc) = 1 ), pre_main as ( select a.sku_group, b.cut_size_formation_date, b.cut_size_formation_inv, date, ifnull(sum(case when date >= b.cut_size_formation_date then gross_quantity end),0) as quant from snitch_db.maplemonk.horizontal_sales_categories a left join cut_size_formation_date b on a.sku_group = b.sku_group where type = \'Shopify\' and date >= \'2025-07-01\' and a.sku_group in (select sku_group from cut_size_formation_date) group by 1,2,3,4 ), current_inv as ( select sku_group, sum(TOTAL_INVENTORY) AS current_inventory FROM snitch_db.maplemonk.cut_size_analysis where date = current_date group by 1 ) select a.*, b.current_inventory from pre_main a left join current_inv b on a.sku_group = b.sku_group",
